<?php require_once __DIR__ . '/inc_app.php'; require_login(); if (!is_admin()) redirect('index.php');
if ($_SERVER['REQUEST_METHOD']==='POST') {
  if (isset($_POST['delete'])) execute_query('DELETE FROM services WHERE id=?', 'i', [(int)$_POST['id']]);
  if (isset($_POST['save'])) execute_query('UPDATE services SET title=?,category=?,price=? WHERE id=?', 'ssdi', [$_POST['title'], $_POST['category'], (float)$_POST['price'], (int)$_POST['id']]);
  redirect('admin-services.php');
}
$rows = fetch_all('SELECT s.*,u.name artist FROM services s JOIN users u ON u.id=s.user_id ORDER BY s.id DESC'); ?>
<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Услуги админ</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><?php include 'admin_header.php'; ?><div class="container py-4"><h1>Услуги</h1><table class="table table-sm"><tr><th>ID</th><th>Художник</th><th>Название</th><th>Категория</th><th>Цена</th><th></th></tr><?php foreach($rows as $r): ?><tr><form method="post"><td><?= (int)$r['id']; ?><input type="hidden" name="id" value="<?= (int)$r['id']; ?>"></td><td><?= h($r['artist']); ?></td><td><input class="form-control form-control-sm" name="title" value="<?= h($r['title']); ?>"></td><td><input class="form-control form-control-sm" name="category" value="<?= h($r['category']); ?>"></td><td><input class="form-control form-control-sm" name="price" type="number" value="<?= (int)$r['price']; ?>"></td><td class="d-flex gap-1"><button class="btn btn-sm btn-outline-dark" name="save">Сохранить</button><button class="btn btn-sm btn-outline-danger" name="delete">Удалить</button></td></form></tr><?php endforeach; ?></table></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script></body></html>
